    out.put("HarvesterPortal", new NpcScripts.Entry(
        "HarvesterPortal",
        "NPC AddOn/HarvesterPortal.cpp",
        "HarvesterPortalNPC",
        "InitTalk\n\nBegin\n\"\"\nIF(IsInRange(4))\n\tIF((CheckItem(__OBJ_HEL_SOULSTONE) >= 1) && (CheckItem(__OBJ_JORMUNGAND_SOULSTONE) >= 1) && (CheckItem(__OBJ_FENRIR_SOULSTONE) >= 1))\n\t\tTakeItem(__OBJ_HEL_SOULSTONE)\n\t\tTakeItem(__OBJ_JORMUNGAND_SOULSTONE)\n\t\tTakeItem(__OBJ_FENRIR_SOULSTONE)\n\t\tPRIVATE_SYSTEM_MESSAGE(INTL(\"${npc.cpp.intl.12275}\"))\n\t\tPRIVATE_SYSTEM_MESSAGE(INTL(\"${npc.cpp.intl.12008}\"))\n\t\tCastSpellTarget(__SPELL_HARVESTER_RETURN_TELEPORT)\n\t\tTELEPORT(2710, 1040, 1)\n\tELSE\n\t\tPRIVATE_SYSTEM_MESSAGE(INTL(\"${npc.cpp.intl.11906}\"))\n\tENDIF\nELSE\n\tPRIVATE_SYSTEM_MESSAGE(INTL(\"${npc.cpp.intl.7349}\"))\nENDIF  \nBREAK\n\nDefault\nINTL(\"${npc.cpp.intl.7353}\")\n\nEndTalk",
        Map.ofEntries(
              Map.entry("OnInitialise", "\n\tNPCstructure::OnInitialise( UNIT_FUNC_PARAM );\n\tWorldPos wlPos = { 0,0,0 };\n\tself->SetDestination( wlPos );\n\tself->Do( nothing );\n\tself->SetCanMove( FALSE );\n")
          )));
    out.put("HeadhunterWajpoothin", new NpcScripts.Entry(
        "HeadhunterWajpoothin",
        "NPC Stoneheim/HeadhunterWajpoothin.cpp",
        "HeadhunterWajpoothinNPC",
        "InitTalk\n\nBegin\nINTL(\"${npc.cpp.intl.8247}\")  \n\t\nCommand2(INTL(\"${npc.cpp.intl.483}\"),INTL(\"${npc.cpp.intl.485}\"))\nINTL(\"${npc.cpp.intl.8248}\")\n\nCommand3(INTL(\"${npc.cpp.intl.489}\"),INTL(\"${npc.cpp.intl.3696}\"),INTL(\"${npc.cpp.intl.487}\"))\nINTL(\"${npc.cpp.intl.8249}\")\n\nCommand(INTL(\"${npc.cpp.intl.8156}\"))\nINTL( 8250, \"Yu bring me, um... handful of scalps ov odder tribe, und I \"\n\"give yew a \\\"Skraugbashor\\\" \\\"Mace\\\".\")\n \nCmdAND(INTL(\"${npc.cpp.intl.8251}\"),INTL(\"${npc.cpp.intl.8252}\"))\n\"\"\nIF (CheckItem(__OBJ_MOON_TUG_SCALP)<5)\n\tConversation\n\tINTL( 8253, \"Me like dat mace, me gots myself a guud lots of dem. Me can give yew \"\n\t\"sum if yew bring me \\\"scalps\\\".\")\nELSE\n\tConversation\n\tINTL( 8254, \"OOOGYAH! Dat is guud! Yew gots lots of scalps! Me takes dem und me gives \"\n\t\"yew a \\\"Skraugbashor\\\" \\\"Mace\\\". Yew agrees?\")\n\tSetYesNo(TakeScalps)\nENDIF\n \nYES(TakeScalps)\n\tIF (CheckItem(__OBJ_MOON_TUG_SCALP)<5) \n\t\tConversation\n\t\tINTL(\"${npc.cpp.intl.8255}\")\n\t\tFIGHT \n\tELSE\n\t\tConversation\n\t\tINTL(\"${npc.cpp.intl.8256}\")\n\t\tFOR(0,5)\n\t\t\tTakeItem(__OBJ_MOON_TUG_SCALP)\n\t\tENDFOR\n\t\tGiveItem(__OBJ_SKRAUGBASHOR_MACE)\n\t\tPRIVATE_SYSTEM_MESSAGE(INTL(\"${npc.cpp.intl.8257}\")) \n\t\t;int nExpReward = USER_LEVEL*1000;\n\t\tPRIVATE_SYSTEM_MESSAGE(FORMAT(INTL(\"${npc.cpp.intl.7982}\"), nExpReward) ) \n\t\tGiveXP(nExpReward)\n\tENDIF \n\t\nNO(TakeScalps)\n\tConversation\n\tINTL(\"${npc.cpp.intl.8258}\")\n\nYesNoELSE(TakeScalps)\n\tConversation\n\tINTL(\"${npc.cpp.intl.8259}\")\n\tSetYesNo(TakeScalps)\n\nCommand4(INTL(\"${npc.cpp.intl.695}\"),INTL(\"${npc.cpp.intl.696}\"),INTL(\"${npc.cpp.intl.697}\"),INTL(\"${npc.cpp.intl.698}\"))\nINTL(\"${npc.cpp.intl.8260}\")\nFIGHT\n\nCommand5(INTL(\"${npc.cpp.intl.519}\"),INTL(\"${npc.cpp.intl.518}\"),INTL(\"${npc.cpp.intl.520}\"),INTL(\"${npc.cpp.intl.517}\"),INTL(\"${npc.cpp.intl.521}\"))\nINTL(\"${npc.cpp.intl.8261}\")\nBREAK\n\nDefault\n\"\"\nIF (rnd.roll(dice(1,2)) ) \n\tConversation\n\tINTL(\"${npc.cpp.intl.8262}\")\nELSE\n\tConversation\n\tINTL(\"${npc.cpp.intl.8263}\")\nENDIF\n\n\nEndTalk",
        Map.of()));
