    out.put("Iraltok", new NpcScripts.Entry(
        "Iraltok",
        "NPCs/Iraltok.cpp",
        "IraltokNPC",
        "InitTalk\n\nBegin\nINTL( 1380, \"I, the seeker of \\\"knowledge\\\", greet you, my friend. Perhaps I could \\\"heal\\\" \"\n\"your wounds if you are in pain. I am also a great \\\"arcane\\\" \\\"scribe\\\" and may be \"\n\"of assistance if you are interested in magical lore.\")\n\nCommand(INTL(\"${npc.cpp.intl.1381}\"))\nINTL( 1382, \"I have the unending task of collecting knowledge and transcribing it \"\n\"to books so that others may later \\\"learn\\\" from them.\")\n\n\nCommand(INTL(\"${npc.cpp.intl.1383}\"))\nINTL( 1384, \"Arcane scribes such as myself use \\\"runic\\\" \\\"scripting\\\" \\\"kits\\\" in order to \"\n\"create \\\"blank\\\" \\\"magic\\\" \\\"scrolls\\\" that are later used to inscribe powerful \"\n\"magics.\")\n\nCommand(INTL(\"${npc.cpp.intl.1385}\"))\nINTL( 1386, \"In order to create such a kit, I need a pouch of yellow powder, a vial of \"\n\"spider venom, a flask of goblin blood, a diamond, and a feather. I ask a \"\n\"modest fee of 1,000 gold pieces to make the kit for you. Please gather all \"\n\"I need and mention \\\"make\\\" \\\"runic\\\" \\\"kit\\\" when you're all set.\")\n\nCommand(INTL(\"${npc.cpp.intl.1175}\"))\nINTL( 1387, \"I cannot make such scrolls myself, but I heard that some wizards in Windhowl \"\n\"could help you with this.\")\n\nCommand(INTL(\"${npc.cpp.intl.1388}\"))\n\"\"\nIF (CheckItem(__OBJ_POUCH_OF_YELLOW_POWDER)>=1 AND (CheckItem(__OBJ_DIAMOND)>=1) AND (CheckItem(__OBJ_FLASK_OF_GOBLIN_BLOOD)>=1) AND (CheckItem(__OBJ_FEATHER)>=1) AND (CheckItem(__OBJ_VIAL_OF_SPIDER_VENOM)>=1) AND (Gold>=1000))\n\tTakeItem(__OBJ_POUCH_OF_YELLOW_POWDER)\n\tTakeItem(__OBJ_DIAMOND)\n\tTakeItem(__OBJ_FLASK_OF_GOBLIN_BLOOD)\n\tTakeItem(__OBJ_FEATHER)\n\tTakeItem(__OBJ_VIAL_OF_SPIDER_VENOM)\n\tTakeGold(1000)\n\tGiveItem(__OBJ_RUNIC_SCRIPTING_KIT)\n\tConversation\n\tINTL( 1389, \"There we go. You're all set, now. Thanks for doing business with me. Please tell \"\n\t\"all your friends about me, I'd love to help them too.\")\nELSE\n\tConversation\n\tINTL( 1390, \"You're missing some components, I'm afraid. Perhaps you should draw a checklist: \"\n\t\"a pouch of yellow powder, a diamond, a feather, a flask of goblin blood and a \"\n\t\"vial of spider venom. Oh, and a thousand gold pieces wouldn't hurt either, if \"\n\t\"it's all the same to you. Please come again.\")\nENDIF\n\nCommand(INTL(\"${npc.cpp.intl.569}\"))\n\"\"\nIF (USER_MAXHP == USER_HP)\n    Conversation\n    INTL(\"${npc.cpp.intl.1147}\")\nELSEIF (USER_LEVEL <= 10)\n    Conversation\n    INTL( 1391, \"I have healed all your wounds my friend. Remember that once you will \"\n    \"be over level 10, I will charge you a small amount of gold pieces for \"\n    \"this service.\")\n    CastSpellTarget(__SPELL_NPC_CANTRIP_SERIOUS_HEAL)\n    HealPlayer(USER_MAXHP)\n\t PRIVATE_SYSTEM_MESSAGE(INTL(\"${npc.cpp.intl.7510}\")) \nELSE\n    Conversation\n\t    FORMAT(INTL(\"${npc.cpp.intl.1146}\"),(USER_MAXHP-USER_HP) / 2)\n    SetYesNo(HEAL)\nENDIF\n\n \nYES(HEAL)\nIF (USER_MAXHP == USER_HP)\n    Conversation\n    INTL(\"${npc.cpp.intl.1147}\")\nELSE\n    IF (Gold < ((USER_MAXHP-USER_HP)/2))\n        IF (Gold > 0) \n            Conversation\n            INTL( 1392, \"You did not have enough gold pieces but I have healed a few of your wounds \"\n            \"nonetheless for what you could spare.\")            \t\t\t\t\n\t\t\t\tPRIVATE_SYSTEM_MESSAGE(FORMAT(INTL(\"${npc.cpp.intl.7513}\"), Gold) ) \n\t\t\t\tPRIVATE_SYSTEM_MESSAGE(INTL(\"${npc.cpp.intl.7512}\")) \t\n\t\t\t\tCastSpellTarget(__SPELL_NPC_CANTRIP_SERIOUS_HEAL)\n\t\t\t\tHealPlayer(Gold*2)              \n\t\t\t\tTakeGold(Gold) \t\t\t\t\n\t\t\tELSE\n            Conversation\n            INTL( 1393, \"You do not have enough gold pieces to be healed. You will have to find \"\n            \"have to find the gold first.\")\n        ENDIF\n    ELSE        \n        Conversation\n        INTL( 1394, \"Thank you for this generous donation. Your wounds are now healed.  \"\n        \"Please feel free to come back if you need more healing.\")\t\t  \n\t\t  PRIVATE_SYSTEM_MESSAGE(FORMAT(INTL(\"${npc.cpp.intl.7513}\"), ((USER_MAXHP-USER_HP) /2) ) ) \n\t\t  PRIVATE_SYSTEM_MESSAGE(INTL(\"${npc.cpp.intl.7510}\")) \t\t  \n\t\t  TakeGold( ( (USER_MAXHP-USER_HP) / 2) )\n\t\t  HealPlayer(USER_MAXHP)        \n\t\t  CastSpellTarget(__SPELL_NPC_CANTRIP_SERIOUS_HEAL)\t\t\t\n    ENDIF\nENDIF\n\nNO(HEAL)\n     Conversation\n     INTL(\"${npc.cpp.intl.1239}\")\n\nYesNoELSE(HEAL)\n     Conversation\n     INTL(\"${npc.cpp.intl.1239}\")\n\nCommand2(INTL(\"${npc.cpp.intl.483}\"),INTL(\"${npc.cpp.intl.485}\"))\nINTL(\"${npc.cpp.intl.1395}\")\n\nCommand3(INTL(\"${npc.cpp.intl.489}\"),INTL(\"${npc.cpp.intl.485}\"),INTL(\"${npc.cpp.intl.487}\"))\nINTL( 1396, \"My task is as endless as time itself. I seek all \\\"knowledge\\\" and transcribe \"\n\"it into \\\"books\\\".\")\n\nCommand3(INTL(\"${npc.cpp.intl.509}\"),INTL(\"${npc.cpp.intl.510}\"),INTL(\"${npc.cpp.intl.582}\"))\nINTL(\"${npc.cpp.intl.1397}\")\n\nCommand(INTL(\"${npc.cpp.intl.523}\"))\nINTL(\"${npc.cpp.intl.1398}\")\n\nCommand(INTL(\"${npc.cpp.intl.1399}\"))\nINTL( 1400, \"Urtanar is a great place. Many say it is the greatest tower of magic.  \"\n\"I was trained there and learned much about the ways of \\\"magic\\\". Even \"\n\"\\\"Uranos\\\" was once an apprentice there. Urtanar is in the middle of a \"\n\"great continent southwest of here. Perhaps one day you will be able to \"\n\"travel there.\")\n\nCommand(INTL(\"${npc.cpp.intl.1096}\"))\nINTL( 1401, \"I'm always happy to help an initiate with his spells. There are several \"\n\"\\\"spells\\\" I can teach you.\")\n\nCommand3(INTL(\"${npc.cpp.intl.700}\"),INTL(\"${npc.cpp.intl.495}\"),INTL(\"${npc.cpp.intl.496}\"))\nINTL(\"${npc.cpp.intl.7514}\")\nCreateSkillList\n\tAddTeachSkill (__SPELL_FIRE_DART, 5, 532)\n\tAddTeachSkill (__SPELL_FLAMING_ARROW, 8, 5300)\nSendTeachSkillList\n\nCommand(INTL(\"${npc.cpp.intl.1424}\"))\nINTL( 1425, \"Uranos is one of the greatest wizards in the kingdom of \\\"Goldmoon\\\".  He is \"\n\"also the oldest.\")\n\nCommand(INTL(\"${npc.cpp.intl.753}\"))\nINTL( 1426, \"Goldmoon is the kingdom regrouping the islands of Arakas, which is the one \"\n\"you are currently on, and Raven's Dust, where the king's castle is.\")\n\nCommand(INTL(\"${npc.cpp.intl.1427}\"))\nINTL( 1428, \"Yes, we have hundreds of them in our \\\"library\\\". In fact, we have so many \"\n\"we cannot count them all.\")\n\nCommand(INTL(\"${npc.cpp.intl.1429}\"))\nINTL(\"${npc.cpp.intl.1430}\")\n\nCommand3(INTL(\"${npc.cpp.intl.519}\"),INTL(\"${npc.cpp.intl.518}\"),INTL(\"${npc.cpp.intl.517}\"))\nINTL(\"${npc.cpp.intl.961}\") BREAK\n\nDefault\nINTL(\"${npc.cpp.intl.1431}\")\n\nEndTalk",
        Map.ofEntries(
              Map.entry("OnAttacked", "\n\tswitch(rnd(0, 1)){\n\tcase 0: SHOUT(INTL(\"${npc.cpp.intl.1378}\")); break;\n\tcase 1: SHOUT(INTL(\"${npc.cpp.intl.1379}\")); break;\n\t}\n\n\tself->Do(flee);\n\tself->SetTarget(target);\n\tNPCstructure::OnAttacked( UNIT_FUNC_PARAM );\n")
          )));
    out.put("IroualKnowall", new NpcScripts.Entry(
        "IroualKnowall",
        "NPC WindHowl/IroualKnowall.cpp",
        "IroualKnowallNPC",
        "InitTalk\n\nBegin\nINTL(\"${npc.cpp.intl.2359}\")\n\nCommand2(INTL(\"${npc.cpp.intl.483}\"),INTL(\"${npc.cpp.intl.485}\"))\nINTL( 2360, \"I am Iroual Knowall and I know just about everything there is to know about \"\n\"\\\"drinks\\\", my friend!\")\n\nCommand3(INTL(\"${npc.cpp.intl.489}\"),INTL(\"${npc.cpp.intl.488}\"),INTL(\"${npc.cpp.intl.487}\"))\nINTL( 2361, \"I am the barman and innkeeper of the Drunken Dragon's Inn. It's a very fine \"\n\"tavern, to say the least. I've been its owner for more than twenty years \"\n\"now! But where are my manners? Would you like a \\\"drink\\\"? We've got the \"\n\"very best ale in the whole town!\")\n\nCommand3(INTL(\"${npc.cpp.intl.509}\"),INTL(\"${npc.cpp.intl.510}\"),INTL(\"${npc.cpp.intl.582}\"))\nINTL( 2362, \"Balork cursed you, you say? I'm sorry to hear that. If \\\"Annabelle\\\" the \"\n\"Blessed One was still here, she might be able to help you. But she's long \"\n\"gone, now. I hear a troll took her away to feast upon her.\") \n\nCommand(INTL(\"${npc.cpp.intl.523}\"))\nINTL( 2363, \"Oh, I don't know for sure if she's dead or alive, but she left us to find \"\n\"her true love years ago... Some say she lives with a troll, now. Me? I \"\n\"just think it's hogwash and she died.\")\n\nCommand(INTL(\"${npc.cpp.intl.2364}\"))\nINTL(\"${npc.cpp.intl.2365}\")\n\nCommand(INTL(\"${npc.cpp.intl.1886}\"))\nINTL( 7225, \"For 100 GP, I'll tell you about your karma. That comes with a good meal, so it's \"\n\"not a total waste. Will you pay?\")\nSetYesNo(KARMA)\n\nYES(KARMA)\nConversation\nINTL(\"${npc.cpp.intl.7226}\")\nIF (Gold >= 100)\n\tTakeGold(100)\n\tIF (USER_KARMA>=400)\n\t\tConversation\n\t\tINTL(\"${npc.cpp.intl.7211}\")\n\tELSEIF (USER_KARMA>=300)\n\t\tConversation\n\t\tINTL(\"${npc.cpp.intl.7212}\")\n\tELSEIF (USER_KARMA>=200)\n\t\tConversation\n\t\tINTL( 7227, \"I hear you're Redeemed, which means you've accomplished a great deal of good deeds, but \"\n\t\t\"there's still room for improvement. Keep this up and you'll become a Blessed.\")\n\tELSEIF (USER_KARMA>=100)\n\t\tConversation\n\t\tINTL( 7228, \"You're a Good person, which is more than I can say about half the population of this island. Don't give up, \"\n\t\t\"you're on the right path to become a Redeemed.\")\n\tELSEIF (USER_KARMA>-100)\n\t\tConversation\n\t\tINTL( 7229, \"You're essentially unaligned, right between Good and Evil. You'll have to work harder one way or the other \"\n\t\t\"to answer your true calling.\")\n\tELSEIF( USER_KARMA <= -400 )\n\t\tConversation\n\t\tINTL( 7230, \"Anyone can see you're a Bane. That's as evil as you're likely to get. I'm not sure congratulations are in \"\n\t\t\"order, so if you'll excuse me, I've got other customers to attend.\")\n\tELSEIF (USER_KARMA<=-300)\n\t\tConversation\n\t\tINTL( 7231, \"Well, what do you know, you're a Cursed! We don't like your kind much around here, but at least you haven't \"\n\t\t\"fallen to the level of Impure yet. There's still hope for you.\")\n\tELSEIF (USER_KARMA<=-200)\n\t\tConversation\n\t\tINTL( 7232, \"You're Malignant, and that's no way to go, if you ask me. Keep this up and you'll become a Cursed. You should \"\n\t\t\"consider the path of good, my friend. Evil begets evil, and nothing good can come of that.\")\n\tELSEIF (USER_KARMA<=-100)\n\t\tConversation\n\t\tINTL( 7233, \"You're Evil, plain and simple, but you haven't become Malignant yet. There's still time for you to turn to good. \"\n\t\t\"At least I think so.\")\n\tELSE\n\t\tConversation\n\t\tINTL(\"${npc.cpp.intl.7220}\")\n\tENDIF\nELSE\n\tConversation\n\tINTL(\"${npc.cpp.intl.7234}\")\nENDIF\n\nNO(KARMA)\nConversation\nINTL(\"${npc.cpp.intl.7235}\")\n\nYesNoELSE(KARMA)\nConversation\nINTL(\"${npc.cpp.intl.7236}\")\nSetYesNo(KARMA)\n\nCommand(INTL(\"${npc.cpp.intl.1346}\"))\nINTL( 2366, \"Here at the Drunken Dragon's Inn, we have the best ale in all of \\\"Goldmoon\\\". \"\n\"The king himself gets his supplies from here! \")\n\nCommand(INTL(\"${npc.cpp.intl.753}\"))\nINTL( 3632, \"Are you some kind of traveler? if you want to know about Goldmoon, just ask \"\n\"people about it. I don't have time to answer questions now.\")\n\nCommand5(INTL(\"${npc.cpp.intl.518}\"),INTL(\"${npc.cpp.intl.517}\"),INTL(\"${npc.cpp.intl.519}\"),INTL(\"${npc.cpp.intl.521}\"),INTL(\"${npc.cpp.intl.520}\"))\nINTL(\"${npc.cpp.intl.973}\") BREAK\n\nDefault\nINTL(\"${npc.cpp.intl.2368}\")\n\nEndTalk",
        Map.of()));
