    out.put("Malaar", new NpcScripts.Entry(
        "Malaar",
        "NPC WindHowl/Malaar.cpp",
        "MalaarNPC",
        "InitTalk\n\nBegin\nINTL(\"${npc.cpp.intl.2541}\")\n\nCommand2(INTL(\"${npc.cpp.intl.483}\"),INTL(\"${npc.cpp.intl.485}\"))\nINTL(\"${npc.cpp.intl.2542}\")\n\nCommand3(INTL(\"${npc.cpp.intl.489}\"),INTL(\"${npc.cpp.intl.488}\"),INTL(\"${npc.cpp.intl.487}\"))\nINTL( 2543, \"I am a bishop of \\\"Artherk\\\". It is my life's work to follow the path of \"\n\"light.\")\n\nCommand3(INTL(\"${npc.cpp.intl.509}\"),INTL(\"${npc.cpp.intl.510}\"),INTL(\"${npc.cpp.intl.511}\"))\nINTL( 2544, \"Ach! So that fiend Balork has cursed you too? I know a traveller to whom it \"\n\"happened, a long time ago... When I saw him again, he said something about \"\n\"a certain \\\"Annabelle\\\" curing him.\")\n\nCommand(INTL(\"${npc.cpp.intl.523}\"))\nINTL( 2545, \"Young, lovely Annabelle, how we miss her! She could heal the sick and comfort \"\n\"the downtrodden. She would hear your plight and help you, no doubt. If she \"\n\"were still alive, that is.\")\n\nCommand(INTL(\"${npc.cpp.intl.2546}\"))\n\"\"\nIF (Gold>10000)\n Conversation\n\tINTL( 2547, \"We would gladly accept a donation from you, if you would be so kind as \"\n\t\"to make one. Would you perhaps have 10,000 gold pieces to offer to \"\n\t\"Artherk?\")\n\tSetYesNo(DONATION)\nELSE\n Conversation\n INTL( 2548, \"We do accept donations, but not from people who are not rich. Once you \"\n \"have made your fortune, please return and we will be glad to take your \"\n \"money in exchange for Artherk's blessings.\")\nENDIF\n\nYES(DONATION)\nIF (Gold>=10000)\n\tConversation\n\tINTL( 2549, \"That is most generous of you!! Thank you so much! No doubt, Artherk \"\n\t\"will bless you for this.\")\n\tIF (USER_KARMA<(100*(CheckFlag(__QUEST_ISLAND_ACCESS)+1)))\n\t\tGiveKarma(20*(500-USER_KARMA)/500)\n\tENDIF\n\tTakeGold(10000)\nELSE\t\n\tConversation\n\tINTL(\"${npc.cpp.intl.11727}\") \nENDIF\n\n\nNO(DONATION)\n\tConversation\n\tINTL( 2550, \"Ah, that is too bad indeed... Perhaps you would not mind giving \"\n\t\"a smaller donation, around a thousand gold pieces?\")\n\tSetYesNo(DONATION2)\nYesNoELSE(DONATION)\n\tConversation\n\tINTL(\"${npc.cpp.intl.2551}\")\n\tSetYesNo(DONATION)\n\nYES(DONATION2)\n\nIF (Gold>=1000)\n\tConversation\n\tINTL(\"${npc.cpp.intl.2552}\")\n\tIF (USER_KARMA<(75*(CheckFlag(__QUEST_ISLAND_ACCESS)+1)))\n\t\tGiveKarma(10*(500-USER_KARMA)/500)\n\tENDIF\n\tTakeGold(1000)\nELSE\t\n\tConversation\n\tINTL(\"${npc.cpp.intl.11727}\") \nENDIF\n\n\nNO(DONATION2)\n\tConversation\n\tINTL( 2553, \"I... see. Then perhaps you would be content with a simple donation of \"\n\t\"250 gold pieces?\")\n\tSetYesNo(DONATION3)\nYesNoELSE(DONATION2)\n\tConversation\n\tINTL(\"${npc.cpp.intl.2554}\")\n\tSetYesNo(DONATION2)\n\nYES(DONATION3)\nIF (Gold>=250)\n\tConversation\n\tINTL(\"${npc.cpp.intl.2555}\")\n\tIF (USER_KARMA<(50*(CheckFlag(__QUEST_ISLAND_ACCESS)+1)))\n\t\tGiveKarma(5*(500-USER_KARMA)/500)\n\tENDIF\n\tTakeGold(250)\nELSE\t\n\tConversation\n\tINTL(\"${npc.cpp.intl.11727}\") \nENDIF\n\n\nNO(DONATION3)\n\tConversation\n\tINTL( 2556, \"Ah... Well, then perhaps you have changed your mind and should \"\n\t\"return when you feel like being generous. May Artherk light your \"\n\t\"path.\")\nYesNoELSE(DONATION3)\n\tConversation\n\tINTL(\"${npc.cpp.intl.2557}\")\n\tSetYesNo(DONATION3)\n\nCommand(INTL(\"${npc.cpp.intl.1243}\"))\nINTL( 2558, \"Artherk is the god of mending and help. He is the only god worshiped \"\n\"in the kingdom of \\\"Goldmoon\\\", I believe. Most of his many followers have \"\n\"the unending task of helping people and praying for those lost in darkness.\")\n\nCommand(INTL(\"${npc.cpp.intl.753}\"))\nINTL( 2559, \"Ahhh, what a great kingdom it is. Our fair King \\\"Theodore\\\" rules \"\n\"wisely and the people are kind of heart. None follow any god other than the \"\n\"great \\\"Artherk\\\", and rightfully so, since he is the only god worshipped \"\n\"by our church. There is also a long forgotten \\\"temple\\\" on Goldmoon, but I \"\n\"do not know if it was dedicated to \\\"Artherk\\\".\")\n\nCommand(INTL(\"${npc.cpp.intl.754}\"))\nINTL( 2560, \"Ahhh! What a wonderful king! He sends us \\\"donations\\\" every month and, in \"\n\"return, we tell everyone how great a king he is.\")\n\nCommand(INTL(\"${npc.cpp.intl.2379}\"))\nINTL( 2561, \"There are many churches of Artherk throughout the land. Most of the other \"\n\"churches follow a dark path, however. Beware of those that hide their work \"\n\"from the eyes of the people.\")\n\nCommand(INTL(\"${npc.cpp.intl.1365}\"))\nINTL( 2562, \"That ancient temple? Oh, well, I do not know much about it. It lies in \"\n\"the forest in the center of Arakas. I think it is near the center but \"\n\"I don't have any time to spend on finding such a mysterious place.\")\n\n// Command(INTL(\"${npc.cpp.intl.2563}\"))\n// INTL( 2564, \"The forest of Mato is great indeed. Further to the north, there is a druid \"\n// \"encampment and, not far from there, lie the dark \\\"caves\\\", home to the goblins. \"\n// \"You can reach almost every location on Arakas from Mato.\")\n// \n//Command(INTL(\"${npc.cpp.intl.881}\"))\n//INTL( 2565, \"What can I say, they're just dumb and slow creatures that only know how to \"\n//\"fight. We'll have no problem dealing with them.\")\n\nCommand(INTL(\"${npc.cpp.intl.515}\"))\nINTL(\"${npc.cpp.intl.2566}\")\n\nCommand5(INTL(\"${npc.cpp.intl.518}\"),INTL(\"${npc.cpp.intl.517}\"),INTL(\"${npc.cpp.intl.519}\"),INTL(\"${npc.cpp.intl.521}\"),INTL(\"${npc.cpp.intl.520}\"))\nINTL(\"${npc.cpp.intl.2567}\") BREAK\n\nDefault\nINTL(\"${npc.cpp.intl.2220}\")\n\nEndTalk",
        Map.of()));
    out.put("MalachaiFatebringer", new NpcScripts.Entry(
        "MalachaiFatebringer",
        "NPC Stoneheim/MalachaiFatebringer.cpp",
        "MalachaiFatebringerNPC",
        "InitTalk\t \n\nBegin\nINTL(\"${npc.cpp.intl.7964}\")\nPRIVATE_SYSTEM_MESSAGE(INTL(\"${npc.cpp.intl.7965}\"))\n\t\nCommand2(INTL(\"${npc.cpp.intl.483}\"),INTL(\"${npc.cpp.intl.485}\"))\nINTL(\"${npc.cpp.intl.7966}\")\nPRIVATE_SYSTEM_MESSAGE(INTL(\"${npc.cpp.intl.7967}\"))\n \nCommand3(INTL(\"${npc.cpp.intl.489}\"),INTL(\"${npc.cpp.intl.3696}\"),INTL(\"${npc.cpp.intl.487}\"))\nINTL(\"${npc.cpp.intl.7968}\")\nPRIVATE_SYSTEM_MESSAGE(INTL(\"${npc.cpp.intl.7969}\"))\n\nCommand2(INTL(\"${npc.cpp.intl.554}\"),INTL(\"${npc.cpp.intl.896}\"))\nINTL( 7970, \"I have no help to give, nor quest to suggest, but should you happen to have \\\"Scrolls\\\" \\\"of\\\" \"\n\"\\\"Horse\\\" \\\"Friendship\\\" on you, be sure to drop by and let me know.\")\nPRIVATE_SYSTEM_MESSAGE(INTL(\"${npc.cpp.intl.7971}\"))\n\nCmdAND3(INTL(\"${npc.cpp.intl.1159}\"),INTL(\"${npc.cpp.intl.10221}\"),INTL(\"${npc.cpp.intl.7973}\"))\n\"\"\nIF(CheckItem(__OBJ_SCROLL_OF_HORSE_FRIENDSHIP) < 1)\n\tConversation\n\tINTL( 7974, \"Those items should NEVER leave Centaur hands. I'm glad to see you have none on yourself, \"\n\t\"or I might be very, very displeased.\")\nELSE\n\tConversation\n\tINTL( 7975, \"These scrolls do not belong to you! I take them back, but I am no thief, so here's \"\n\t\"something in return.\")\n\t;int nNumScrollsTaken = rnd.roll(dice(1,CheckItem(__OBJ_SCROLL_OF_HORSE_FRIENDSHIP)));\n\t;int nExpReward = USER_LEVEL*2000*nNumScrollsTaken;\n\tPRIVATE_SYSTEM_MESSAGE(FORMAT(INTL(\"${npc.cpp.intl.7976}\"),nNumScrollsTaken))\t\n\tPRIVATE_SYSTEM_MESSAGE(FORMAT(INTL(\"${npc.cpp.intl.7982}\"), nExpReward) ) \n\tGiveXP(nExpReward)\n\tFOR(0,nNumScrollsTaken)\n\t\tTakeItem(__OBJ_SCROLL_OF_HORSE_FRIENDSHIP)\t\t\n\t\tSWITCH( rnd.roll(dice(1,4)))\n\t\t\tCASE(1)\n\t\t\t\tGiveItem(__OBJ_ASSASSIN_BLADE)\n\t\t\t\tPRIVATE_SYSTEM_MESSAGE(INTL(\"${npc.cpp.intl.7977}\"))\n\t\t\tENDCASE\n\t\t\tCASE(2)\n\t\t\t\tGiveItem(__OBJ_GRIM_BLADE_OF_WAR)\n\t\t\t\tPRIVATE_SYSTEM_MESSAGE(INTL(\"${npc.cpp.intl.7978}\"))\n\t\t\tENDCASE\n\t\t\tCASE(3)\n\t\t\t\tGiveItem(__OBJ_ROBE_OF_HELL)\n\t\t\t\tPRIVATE_SYSTEM_MESSAGE(INTL(\"${npc.cpp.intl.7979}\"))\n\t\t\tENDCASE\n\t\t\tCASE(4)\n\t\t\t\tGiveItem(__OBJ_BOW_OF_CENTAUR_SLAYING)\n\t\t\t\tPRIVATE_SYSTEM_MESSAGE(INTL(\"${npc.cpp.intl.7980}\"))\n\t\t\tENDCASE\n\t\t\tOTHERWISE\n\t\t\t\tConversation\n\t\t\t\tINTL(\"${npc.cpp.intl.7981}\")\n\t\tENDSWITCH\n\tENDFOR\nENDIF\nPRIVATE_SYSTEM_MESSAGE(INTL(\"${npc.cpp.intl.7983}\"))\n\nCmdAND(INTL(\"${npc.cpp.intl.7984}\"),INTL(\"${npc.cpp.intl.7985}\"))\nINTL( 7986, \"That's a poisoned blade. It goes through armor like a hot knife through butter. I'm \"\n\"told mostly thieves use it.\")\nPRIVATE_SYSTEM_MESSAGE(INTL(\"${npc.cpp.intl.7987}\"))\n\nCmdAND3(INTL(\"${npc.cpp.intl.7988}\"),INTL(\"${npc.cpp.intl.7985}\"),INTL(\"${npc.cpp.intl.7989}\"))\nINTL(\"${npc.cpp.intl.7990}\")\n\nPRIVATE_SYSTEM_MESSAGE(INTL(\"${npc.cpp.intl.7987}\"))\n\nCmdAND(INTL(\"${npc.cpp.intl.7991}\"),INTL(\"${npc.cpp.intl.7992}\"))\nINTL( 7993, \"The Robe of Hell is useful to mages who wish to seek immunity against fire and darkness. \"\n\"Perhaps you should try it on and see how it looks on you.\")\nPRIVATE_SYSTEM_MESSAGE(INTL(\"${npc.cpp.intl.7987}\"))\n\nCmdAND3(INTL(\"${npc.cpp.intl.7994}\"),INTL(\"${npc.cpp.intl.7995}\"),INTL(\"${npc.cpp.intl.7996}\"))\nINTL( 7997, \"Aaah, it would be a shame if a human archer started using that bow against my people. \"\n\"I'm certain it would make our king look very bad, wouldn't you agree?\")\nPRIVATE_SYSTEM_MESSAGE(INTL(\"${npc.cpp.intl.7987}\"))\n\nCommand2(INTL(\"${npc.cpp.intl.1072}\"),INTL(\"${npc.cpp.intl.7998}\"))\nINTL( 7999, \"A weakling! He believes in his own sanctimonious, righteous act, but I am not fooled by it. \"\n\"He is guilty of something, and even though he hides it well, I'm confident Zion Thunderheart \"\n\"will eventually expose him.\")\nPRIVATE_SYSTEM_MESSAGE(INTL(\"${npc.cpp.intl.8000}\"))\n\nCommand2(INTL(\"${npc.cpp.intl.8001}\"),INTL(\"${npc.cpp.intl.8002}\"))\nINTL( 8003, \"He should be the king! None of this weak-hearted compassion and nonsensical trading with humans. \"\n\"Let Zion rule and take us on the path to reclaim *our* Stoneheim!\")\n\nPRIVATE_SYSTEM_MESSAGE(INTL(\"${npc.cpp.intl.8004}\") )\n\nCommand2(INTL(\"${npc.cpp.intl.8005}\"),INTL(\"${npc.cpp.intl.8006}\"))\nINTL( 8007, \"Dumb as a doorknob! He can fight pretty good, but his ridiculous equipment is what makes him good, \"\n\"not his skill. Some day, I'll show him who's the better warrior!\")\nPRIVATE_SYSTEM_MESSAGE(INTL(\"${npc.cpp.intl.8008}\"))\n\nCommand2(INTL(\"${npc.cpp.intl.8009}\"),INTL(\"${npc.cpp.intl.8010}\"))\nINTL( 8011, \"A rank amateur! He thinks his manasmithing is better than my manaweaving, but that's because I've \"\n\"never challenged his little creations with my own. I've made swords and armors that could slay him \"\n\"in one blow!\")\nPRIVATE_SYSTEM_MESSAGE(INTL(\"${npc.cpp.intl.8012}\"))\n\nCommand2(INTL(\"${npc.cpp.intl.8013}\"),INTL(\"${npc.cpp.intl.8014}\"))\nINTL( 8015, \"A delusional idiot! I want nothing to do with the likes of him. Religion is for those who do not \"\n\"have the strength to stand proud and tall on their own. I don't need a god to tell me I'm worth \"\n\"something, I already know that!\")\nPRIVATE_SYSTEM_MESSAGE(INTL(\"${npc.cpp.intl.8016}\"))\n\nCommand2(INTL(\"${npc.cpp.intl.8017}\"),INTL(\"${npc.cpp.intl.8018}\"))\nINTL( 8019, \"Brawns with no brains! He thinks he's all that, he thinks he's noble and selfless, but I know better. \"\n\"He and his ilk only want to be seen as great heroes and protectors, when all they do is walk around with \"\n\"a sword and pretend they're something else. It makes me sick!\")\nPRIVATE_SYSTEM_MESSAGE(INTL(\"${npc.cpp.intl.8008}\"))\n\nCommand4(INTL(\"${npc.cpp.intl.695}\"),INTL(\"${npc.cpp.intl.696}\"),INTL(\"${npc.cpp.intl.697}\"),INTL(\"${npc.cpp.intl.698}\"))\nINTL(\"${npc.cpp.intl.8020}\")\nPRIVATE_SYSTEM_MESSAGE(INTL(\"${npc.cpp.intl.8021}\"))\nBREAK\n\nCommand5(INTL(\"${npc.cpp.intl.519}\"),INTL(\"${npc.cpp.intl.518}\"),INTL(\"${npc.cpp.intl.520}\"),INTL(\"${npc.cpp.intl.517}\"),INTL(\"${npc.cpp.intl.521}\"))\nINTL(\"${npc.cpp.intl.1075}\")\nPRIVATE_SYSTEM_MESSAGE(INTL(\"${npc.cpp.intl.8022}\"))\nBREAK\n\nDefault\n\"\"\nIF (rnd.roll( dice(1,2) ) == 1) \n\tConversation\n\tINTL(\"${npc.cpp.intl.3921}\")\nELSE\n\tConversation\n\tINTL(\"${npc.cpp.intl.5250}\")\nENDIF\nPRIVATE_SYSTEM_MESSAGE(INTL(\"${npc.cpp.intl.8023}\"))\n\n\nEndTalk",
        Map.of()));
    out.put("Markam", new NpcScripts.Entry(
        "Markam",
        "NPCs/Markam.cpp",
        "MarkamNPC",
        "InitTalk\n\nBegin\n\"\"\nIF(CheckFlag(__FLAG_ADDON_STORYLINE_PROGRESS) == 21)\n\tConversation\n\tINTL(\"${npc.cpp.intl.11768}\")\nELSE\n\tConversation\n\tINTL( 11769, \"I wish these damned guards would go away. Lord Kirlor doesn't show it, but he's really disturbed \"\n\t\"by their presence.\")\nENDIF\n\nCommand2(INTL(\"${npc.cpp.intl.483}\"),INTL(\"${npc.cpp.intl.485}\"))\nINTL(\"${npc.cpp.intl.1728}\")\n\nCommand3(INTL(\"${npc.cpp.intl.489}\"),INTL(\"${npc.cpp.intl.488}\"),INTL(\"${npc.cpp.intl.487}\"))\nINTL( 1729, \"My duties are numerous in this town. You might say that I am \"\n\"\\\"Lord\\\" \\\"Kirlor\\\"'s assistant.\")\n\nCommand(INTL(\"${npc.cpp.intl.523}\"))\nINTL( 1730, \"Annabelle? I heard she is a lovely lady, but somewhat odd, even though I've never \"\n\"met her.\")\n\nCommand3(INTL(\"${npc.cpp.intl.509}\"),INTL(\"${npc.cpp.intl.510}\"),INTL(\"${npc.cpp.intl.582}\"))\nINTL(\"${npc.cpp.intl.2670}\")\n\nCommand2(INTL(\"${npc.cpp.intl.1435}\"),INTL(\"${npc.cpp.intl.1436}\"))\nINTL( 1731, \"Lord Kirlor has been looking for adventurers lately to help in the protection \"\n\"of the local \\\"merchants\\\".\")\n\nCommand(INTL(\"${npc.cpp.intl.753}\"))\nINTL( 1732, \"It is the kingdom regrouping all the villages on the islands of \\\"Arakas\\\" \"\n\"and \\\"Raven's\\\" \\\"Dust\\\".\")\n\nCommand(INTL(\"${npc.cpp.intl.793}\"))\nINTL(\"${npc.cpp.intl.1733}\")\n\nCommand(INTL(\"${npc.cpp.intl.515}\"))\nINTL(\"${npc.cpp.intl.1734}\")\n\nCommand(INTL(\"${npc.cpp.intl.1257}\"))\nINTL( 1735, \"The merchants are constantly being robbed by \\\"brigands\\\" while trying to \"\n\"cross the forest to \\\"Windhowl\\\". They are having a hard time. Their shops are \"\n\"losing money and all. \")\n\nCommand(INTL(\"${npc.cpp.intl.617}\"))\nINTL(\"${npc.cpp.intl.1736}\")\n\nCommand(INTL(\"${npc.cpp.intl.554}\"))\nINTL(\"${npc.cpp.intl.1737}\")\n\nCommand(INTL(\"${npc.cpp.intl.514}\"))\nINTL( 1738, \"The western town on the island, Windhowl is the biggest town in the \"\n\"kingdom of \\\"Goldmoon\\\". But be careful if you go there because \\\"brigands\\\" \"\n\"and strange creatures have been ambushing careless wanderers lately.\")\n\nCommand(INTL(\"${npc.cpp.intl.565}\"))\nINTL( 2792, \"Brigands have been banding together in large groups to attack our \\\"merchant\\\" \"\n\"carriers. If one could \\\"help\\\" them by bringing a simple report to \"\n\"Lord Sunrock in \\\"Windhowl\\\", it would allow both towns to send \"\n\"guarded merchant caravans at a secret planned time and do business without \"\n\"fearing the interference of the brigands. If you are an adventurer, then \"\n\"by all means, talk to Lord Kirlor in his office and \\\"register\\\" yourself!\")\n\t\t \nCommand(INTL(\"${npc.cpp.intl.1257}\"))\nINTL( 2793, \"These days, it is near impossible for the merchants of our fair city to do business with our \"\n\"sister town, \\\"Windhowl\\\". If you would like to help one of our merchants, you must talk to \"\n\"\\\"Lord\\\" \\\"Kirlor\\\" and \\\"register\\\" yourself. He will then give you a letter that you must \"\n\"give to either \\\"Sigfried\\\" or \\\"Rolph\\\". They'll give you a report that must be delivered \"\n\"to \\\"Lord\\\" \\\"Sunrock\\\" in Windhowl as fast as possible.\")\n\nCommand(INTL(\"${npc.cpp.intl.1648}\"))\nINTL(\"${npc.cpp.intl.2794}\")\n\nCommand(INTL(\"${npc.cpp.intl.2518}\"))\nINTL(\"${npc.cpp.intl.2781}\")\n\nCommand(INTL(\"${npc.cpp.intl.2345}\"))\nINTL(\"${npc.cpp.intl.7163}\")\n\nCommand(INTL(\"${npc.cpp.intl.1436}\"))\nINTL(\"${npc.cpp.intl.2783}\")\n\nCommand(INTL(\"${npc.cpp.intl.514}\"))\nINTL(\"${npc.cpp.intl.2791}\")\n\nCommand(INTL(\"${npc.cpp.intl.513}\"))\nINTL(\"${npc.cpp.intl.1607}\")\n\nCommand5(INTL(\"${npc.cpp.intl.518}\"),INTL(\"${npc.cpp.intl.517}\"),INTL(\"${npc.cpp.intl.519}\"),INTL(\"${npc.cpp.intl.520}\"),INTL(\"${npc.cpp.intl.521}\"))\nINTL(\"${npc.cpp.intl.1740}\") BREAK\n\nDefault\nINTL(\"${npc.cpp.intl.1741}\")\n\nEndTalk",
        Map.ofEntries(
              Map.entry("OnAttacked", "\n\tswitch(rnd(0, 1)){\n\tcase 0: SHOUT(INTL(\"${npc.cpp.intl.1378}\")); break;\n\tcase 1: SHOUT(INTL(\"${npc.cpp.intl.1379}\")); break;\n\t}\n\n\tself->Do(flee);\n\tself->SetTarget(target);\n\tNPCstructure::OnAttacked( UNIT_FUNC_PARAM );\n")
          )));
    out.put("MarnecSunim", new NpcScripts.Entry(
        "MarnecSunim",
        "NPCs/MarnecSunim.cpp",
        "MarnecSunimNPC",
        "InitTalk\n\nBegin\nINTL(\"${npc.cpp.intl.11770}\")\n\nCommand2(INTL(\"${npc.cpp.intl.483}\"),INTL(\"${npc.cpp.intl.485}\"))\nINTL(\"${npc.cpp.intl.1743}\")\n\nCommand(INTL(\"${npc.cpp.intl.1744}\"))\nINTL( 1745, \"My ancestors have been farmers for generations now. I have \\\"secrets\\\" which \"\n\"help me grow food that has made me famous. I am not very rich yet, but I'm \"\n\"sure it's just a matter of time.\")\n\nCommand(INTL(\"${npc.cpp.intl.1746}\"))\nINTL(\"${npc.cpp.intl.1747}\")\n\nCommand3(INTL(\"${npc.cpp.intl.489}\"),INTL(\"${npc.cpp.intl.488}\"),INTL(\"${npc.cpp.intl.487}\"))\nINTL( 1748, \"I am the town's greatest farmer! And I tell you, it isn't going as well as \"\n\"it used to. Those damned \\\"brigands\\\" are really starting to annoy me. \"\n\"It's a shame our town's \\\"army\\\" is too small to give them a good beating. \"\n\"One of these days I tell ya, I'm going to pay them a small visit. \"\n\"It's just that I'm too busy to do it now with my farm and all, you know...\")\n\nCommand3(INTL(\"${npc.cpp.intl.509}\"),INTL(\"${npc.cpp.intl.510}\"),INTL(\"${npc.cpp.intl.582}\"))\nINTL(\"${npc.cpp.intl.820}\")\n\nCommand(INTL(\"${npc.cpp.intl.523}\"))\nINTL(\"${npc.cpp.intl.584}\")\n\nCommand(INTL(\"${npc.cpp.intl.565}\"))\nINTL( 1749, \"They are attacking everyone who tries to cross the forest. Trading with \"\n\"\\\"Windhowl\\\" has been nearly impossible lately because of them. Perhaps \"\n\"you could help the \\\"merchants\\\" doing some business with Windhowl if you \"\n\"are a true adventurer.\")\n\t \nCommand(INTL(\"${npc.cpp.intl.1257}\"))\nINTL( 2795, \"These days, it is near impossible for the merchants of our fair city to do business with our \"\n\"sister town, \\\"Windhowl\\\". If you would like to help one of our merchants, you must talk to \"\n\"\\\"Lord\\\" \\\"Kirlor\\\" and \\\"register\\\" yourself. He will then give you a letter that you must \"\n\"give to either \\\"Sigfried\\\" or \\\"Rolph\\\". They'll give you a report that must be delivered \"\n\"to Lord Sunrock in Windhowl as fast as possible.\")\n\nCommand(INTL(\"${npc.cpp.intl.1648}\"))\nINTL(\"${npc.cpp.intl.2796}\")\n\nCommand(INTL(\"${npc.cpp.intl.2518}\"))\nINTL(\"${npc.cpp.intl.2781}\")\n\nCommand(INTL(\"${npc.cpp.intl.2345}\"))\nINTL(\"${npc.cpp.intl.7163}\")\n\nCommand(INTL(\"${npc.cpp.intl.1436}\"))\nINTL(\"${npc.cpp.intl.2783}\")\n\nCommand(INTL(\"${npc.cpp.intl.513}\"))\nINTL(\"${npc.cpp.intl.1607}\")\n\nCommand(INTL(\"${npc.cpp.intl.514}\"))\nINTL(\"${npc.cpp.intl.1750}\")\n\nCommand(INTL(\"${npc.cpp.intl.1751}\"))\nINTL( 1752, \"Our army is so small that it can't even take out the \\\"brigands\\\"' hideout. \"\n\"Fortunatly, \\\"Murmuntag\\\" sometimes goes in the forest and cleans up the \"\n\"road for a day or two.\")\n\nCommand(INTL(\"${npc.cpp.intl.1037}\"))\nINTL( 1753, \"He's quite a big fellow, I tell you. Not very intelligent, but strong as an \"\n\"ox, maybe even stronger.\")\n\nCommand5(INTL(\"${npc.cpp.intl.518}\"),INTL(\"${npc.cpp.intl.517}\"),INTL(\"${npc.cpp.intl.519}\"),INTL(\"${npc.cpp.intl.520}\"),INTL(\"${npc.cpp.intl.521}\"))\nINTL(\"${npc.cpp.intl.1754}\") BREAK\n\nDefault\nINTL(\"${npc.cpp.intl.1755}\")\n\nEndTalk",
        Map.ofEntries(
              Map.entry("OnAttacked", "\n\tswitch(rnd(0, 1)){\n\tcase 0: SHOUT(INTL(\"${npc.cpp.intl.1378}\")); break;\n\tcase 1: SHOUT(INTL(\"${npc.cpp.intl.1379}\")); break;\n\t}\n\n\tself->Do(flee);\n\tself->SetTarget(target);\nNPCstructure::OnAttacked( UNIT_FUNC_PARAM );\n")
          )));
    out.put("MarsacCred", new NpcScripts.Entry(
        "MarsacCred",
        "NPC WindHowl/MarsacCred.cpp",
        "MarsacCredNPC",
        "InitTalk\n\nBegin\nINTL(\"${npc.cpp.intl.2568}\")\n\nCommand2(INTL(\"${npc.cpp.intl.483}\"),INTL(\"${npc.cpp.intl.485}\"))\nINTL(\"${npc.cpp.intl.2569}\")\n\nCommand3(INTL(\"${npc.cpp.intl.489}\"),INTL(\"${npc.cpp.intl.488}\"),INTL(\"${npc.cpp.intl.487}\"))\nINTL( 2570, \"I am an \\\"elemental\\\" mage, and I help \\\"R'yleth\\\" here in this tower \"\n\"of magic.\")\n\nCommand3(INTL(\"${npc.cpp.intl.509}\"),INTL(\"${npc.cpp.intl.510}\"),INTL(\"${npc.cpp.intl.511}\"))\nINTL(\"${npc.cpp.intl.2670}\")\n\nCommand(INTL(\"${npc.cpp.intl.523}\"))\nINTL(\"${npc.cpp.intl.665}\")\n\nCommand(INTL(\"${npc.cpp.intl.1424}\"))\n\"\"\nIF (CheckFlag (__QUEST_URANOS) == 1)\n GiveFlag (__QUEST_URANOS_INGREDIENTS, 1)\n Conversation\n INTL( 2571, \"So, Uranos needs a special component, eh? Well, he can thank his lucky star that \"\n \"I know exactly what he's looking for. You will have to find some decaying bat \\\"wings\\\" and bring \"\n \"them to him before they crumble to dust. He'll probably need more than one though, so get \"\n \"as many as you can.\") \nELSE\n\tConversation\n\tINTL(\"${npc.cpp.intl.2572}\")\nENDIF\n\nCommand(INTL(\"${npc.cpp.intl.2573}\"))\nINTL( 2574, \"They're just ordinary bat wings... Well, that's not entirely true. Actually, \"\n\"the kind of wing he is looking for only comes from the undead bats that roam \"\n\"in the dungeon under Lighthaven.\")\n\nCommand(INTL(\"${npc.cpp.intl.2575}\"))\nINTL( 2576, \"R'yleth is the current mage \\\"Guildmaster\\\" here in Windhowl. His great \"\n\"power is only matched by his enormous ego. *snicker* But other than that, \"\n\"he truly is a master of magic. He has travelled much and has learned from \"\n\"the greatest magicians that live.\")\n\nCommand(INTL(\"${npc.cpp.intl.1181}\"))\nINTL( 2577, \"These are powerful scrolls indeed. They can help you make a magical item, or to \"\n\"improve an item that is already magical. Would you like me to make one for you?\")\nSetYesNo(MAKESCROLL)\n\nYES(MAKESCROLL)\nConversation\nINTL( 2578, \"Great. All you need is a \\\"blank\\\" \\\"magic\\\" \\\"scroll\\\", a \\\"human\\\" \\\"bone\\\", a \\\"runic\\\" \"\n\"\\\"scripting\\\" \\\"box\\\" and, of course a donation of 4,000 GPs. So shall we proceed?\")\nSetYesNo(MAKESCROLL2)\n\nNO(MAKESCROLL)\nConversation\nINTL(\"${npc.cpp.intl.2579}\")\n\nYesNoELSE(MAKESCROLL)\nConversation\nINTL(\"${npc.cpp.intl.2580}\")\n\nYES(MAKESCROLL2)\nConversation\nINTL(\"${npc.cpp.intl.2581}\")\n IF ((CheckItem(__OBJ_BLANK_MAGIC_SCROLL) >= 1) AND (CheckItem(__OBJ_HUMAN_BONE) >= 1) AND (CheckItem(__OBJ_RUNIC_SCRIPTING_KIT) >= 1) AND (Gold >= 4000))\n\t\tConversation\n\t\tINTL( 2582, \"Very good, very good. A little bit of this, a little bit of that... Let it rest \"\n\t\t\"for a few moments... And here we are!\")\n\t\tTakeItem(__OBJ_BLANK_MAGIC_SCROLL)\n\t\tTakeItem(__OBJ_HUMAN_BONE)\n\t\tTakeGold(4000)\n\t\tGiveItem(__OBJ_SCROLL_OF_ENCHANTMENT)\n\tELSE\n\t\tConversation\n\t\tINTL( 2583, \"Hey! May I remind you what I said earlier? Blank magic scroll, human bone, \"\n\t\t\"a runic scripting kit, 4,000 gold pieces. Come back when you've got everything.\")\n\tENDIF\n\nNO(MAKESCROLL2)\nConversation\nINTL(\"${npc.cpp.intl.712}\")\n\nYesNoELSE(MAKESCROLL2)\nConversation\nINTL(\"${npc.cpp.intl.2584}\")\n\nCommand(INTL(\"${npc.cpp.intl.1175}\"))\nINTL( 2585, \"This type of scroll is required to create \\\"scroll\\\" \\\"of\\\" \\\"enchantment\\\". You should definitely \"\n\"try to acquire a few. All true mages have them and trade them.\")\n\nCommand(INTL(\"${npc.cpp.intl.1673}\"))\nINTL(\"${npc.cpp.intl.2586}\")\n\nCommand(INTL(\"${npc.cpp.intl.1385}\"))\nINTL( 2587, \"You can't make that on your own, you have to check with someone who's specialized in \"\n\"making such kits. I know of a certain Iraltok who could perhaps help you with that.\")\n\nCommand(INTL(\"${npc.cpp.intl.2588}\"))\nINTL( 2589, \"Elemental magic is the base of all things pure. A mage can gather the mana \"\n\"that flows around him and channel it into one of four elements and release the \"\n\"energies in the form of a spell. I control the forces of \\\"water\\\".\")\n\nCommand(INTL(\"${npc.cpp.intl.2590}\"))\nINTL( 2591, \"Althought most of the time, water is peaceful in nature, it can sometimes \"\n\"be devastating. I can show you how to harness the forces of water and \\\"teach\\\" \"\n\"you how to cast water spells, so that you may use these forces to your advantage.\")\n\nCommand3(INTL(\"${npc.cpp.intl.700}\"),INTL(\"${npc.cpp.intl.496}\"),INTL(\"${npc.cpp.intl.495}\"))\nINTL(\"${npc.cpp.intl.7544}\")\nCreateSkillList\n\tAddTeachSkill (__SPELL_FREEZE, 11, 17200)\n\tAddTeachSkill (__SPELL_ICE_BOLT, 13, 25625)\nSendTeachSkillList\n\nCommand(INTL(\"${npc.cpp.intl.2615}\"))\nINTL( 2616, \"The guildmaster's work consists of controlling the research of new spells \"\n\"and the teaching of magic to apprentices. The guildmaster is also often asked \"\n\"to help the city in various matters, mostly political.\")\n\nCommand5(INTL(\"${npc.cpp.intl.518}\"),INTL(\"${npc.cpp.intl.517}\"),INTL(\"${npc.cpp.intl.519}\"),INTL(\"${npc.cpp.intl.521}\"),INTL(\"${npc.cpp.intl.520}\"))\nINTL(\"${npc.cpp.intl.973}\") BREAK\n\nDefault\nINTL(\"${npc.cpp.intl.2617}\")\n\nEndTalk",
        Map.of()));
    out.put("MayorFairweather", new NpcScripts.Entry(
        "MayorFairweather",
        "NPC Stoneheim/MayorFairweather.cpp",
        "MayorFairweatherNPC",
        "InitTalk\n\nBegin\nINTL(\"${npc.cpp.intl.8703}\")\n\t\nCommand2(INTL(\"${npc.cpp.intl.483}\"),INTL(\"${npc.cpp.intl.485}\"))\nINTL(\"${npc.cpp.intl.8704}\")\n\nCommand3(INTL(\"${npc.cpp.intl.489}\"),INTL(\"${npc.cpp.intl.3696}\"),INTL(\"${npc.cpp.intl.487}\"))\nINTL( 8705, \"I am the mayor of Stonecrest. I see to the well-being of \"\n\"the citizens of this town. In this, I have to say that I am fortunate \"\n\"to have one such as \\\"Grant\\\" \\\"Hornkeep\\\" to uphold the law.\") \n\nCommand2(INTL(\"${npc.cpp.intl.8706}\"),INTL(\"${npc.cpp.intl.8305}\"))\nINTL( 8707, \"He is the town's sheriff. It is his duty to enforce the law and stop \"\n\"thieves and skraugs from wreaking havoc around here.\")\n\nCommand(INTL(\"${npc.cpp.intl.1367}\"))\nINTL( 8708, \"I used to be a dragonslayer in my young days. That's before I retired and took this job \"\n\"as Stonecrest's mayor. It's a cushy job compared to fighting dragons, but the politics \"\n\"can really get to you, sometimes. There are days when I miss the 'old life'...\")\n\nCommand(INTL(\"${npc.cpp.intl.11335}\")) \n\"\"\nIF (CheckItem(__OBJ_THANK_YOU_NOTE) < 6)\n\tConversation\n\tINTL(\"${npc.cpp.intl.8712}\")\nELSE\n\tConversation\n\tINTL(\"${npc.cpp.intl.8713}\")\n\tSetYesNo(TakeNotes)\nENDIF\n\nCmdAND3(INTL(\"${npc.cpp.intl.8709}\"),INTL(\"${npc.cpp.intl.8710}\"),INTL(\"${npc.cpp.intl.8711}\"))\n\"\"\nIF (CheckItem(__OBJ_THANK_YOU_NOTE) < 6)\n\tConversation\n\tINTL(\"${npc.cpp.intl.8712}\")\nELSE\n\tConversation\n\tINTL(\"${npc.cpp.intl.8713}\")\n\tSetYesNo(TakeNotes)\nENDIF\n\nYES(TakeNotes)\n\tIF (CheckItem(__OBJ_THANK_YOU_NOTE) < 6)\n\t\tConversation\n\t\tINTL( 8714, \"I'm somewhat disappointed in you. What happened to your notes, all of a sudden? I'm sure you had \"\n\t\t\"at *least* six of them!\")\n\tELSE\n\t\tConversation\n\t\tINTL(\"${npc.cpp.intl.8715}\")\n\t\tFOR(0,6) \n\t\t\tTakeItem(__OBJ_THANK_YOU_NOTE)\n\t\tENDFOR\n\t\tGiveItem(__OBJ_LOST_BLADE_OF_THE_DRAGON)\n\t\tPRIVATE_SYSTEM_MESSAGE(INTL(\"${npc.cpp.intl.8716}\"))\n\t\t;int nExpReward = USER_LEVEL*3000;\n\t\tPRIVATE_SYSTEM_MESSAGE(FORMAT(INTL(\"${npc.cpp.intl.7982}\"), nExpReward) ) \n\t\tGiveXP(nExpReward)\n\tENDIF\n\nNO(TakeNotes)\n\tConversation\n\tINTL(\"${npc.cpp.intl.8717}\")\n\nYesNoELSE(TakeNotes)\n\tConversation\n\tINTL(\"${npc.cpp.intl.8718}\")\n\tSetYesNo(TakeNotes)\n\nCmdAND(INTL(\"${npc.cpp.intl.8719}\"),INTL(\"${npc.cpp.intl.8720}\"))\n\"\"\nIF(CheckItem(__OBJ_CERTIFICATE_OF_RECOGNITION) >= 6)\n\tConversation\n\tINTL( 8721, \"I see you carry many Certificates of Recognition with you. Would you like to \"\n\t\"trade them in for a reward?\")\n\tSetYesNo(TakeCertificate)\nELSEIF(CheckItem(__OBJ_CERTIFICATE_OF_RECOGNITION) >= 1)\n\tConversation\n\tINTL( 8722, \"I see you've got a few of those already. When you have half a dozen, come back \"\n\t\"and visit me, and I'll reward you accordingly.\")\nELSE\n\tConversation\n\tINTL( 8723, \"Certificates of recognition are awarded by the sheriff of this town for great deeds \"\n\t\"done on behalf the the townsfolk.\")\nENDIF\n\nYES(TakeCertificate)\n\tIF (CheckItem( __OBJ_CERTIFICATE_OF_RECOGNITION) < 6 ) \n\t\tConversation\n\t\tINTL( 10222, \"I'm somewhat disappointed in you. What happened to your certificates, all of a sudden? \"\n\t\t\"I'm sure you had at *least* six of them!\")\t\t\n\tELSE\n\t\tConversation\n\t\tINTL(\"${npc.cpp.intl.8724}\")\n\t\tFOR(0,6)\n\t\t\tTakeItem(__OBJ_CERTIFICATE_OF_RECOGNITION)\n\t\tENDFOR\n\t\tGiveItem(__OBJ_LOST_HELM_OF_THE_DRAGON)\n\t\tPRIVATE_SYSTEM_MESSAGE(INTL(\"${npc.cpp.intl.8725}\"))\n\t\t;int nExpReward = USER_LEVEL*2000;\n\t\t;int nGoldReward = USER_LEVEL*1000;\n\t\tPRIVATE_SYSTEM_MESSAGE(FORMAT(INTL(\"${npc.cpp.intl.7982}\"), nExpReward) )\n\t\tPRIVATE_SYSTEM_MESSAGE(FORMAT(INTL(\"${npc.cpp.intl.8726}\"), nGoldReward) )\n\t\tGiveXP(nExpReward)\n\t\tGiveGold(nGoldReward)\n\tENDIF \n\nNO(TakeCertificate)\n\tConversation\n\tINTL(\"${npc.cpp.intl.8727}\")\n\nYesNoELSE(TakeCertificate)\n\tConversation\n\tINTL(\"${npc.cpp.intl.8728}\")\n\tSetYesNo(TakeCertificate)\n\nCmdAND3(INTL(\"${npc.cpp.intl.3999}\"),INTL(\"${npc.cpp.intl.7985}\"),INTL(\"${npc.cpp.intl.1367}\"))\nINTL(\"${npc.cpp.intl.8729}\")\n\nCommand4(INTL(\"${npc.cpp.intl.695}\"),INTL(\"${npc.cpp.intl.696}\"),INTL(\"${npc.cpp.intl.697}\"),INTL(\"${npc.cpp.intl.698}\"))\nINTL(\"${npc.cpp.intl.8730}\")\nBREAK\n\nCommand5(INTL(\"${npc.cpp.intl.519}\"),INTL(\"${npc.cpp.intl.518}\"),INTL(\"${npc.cpp.intl.520}\"),INTL(\"${npc.cpp.intl.517}\"),INTL(\"${npc.cpp.intl.521}\"))\nINTL(\"${npc.cpp.intl.1075}\")\nBREAK\n\nDefault\n\"\"\nIF (rnd.roll(dice(1,2)) == 1)\n   Conversation\n   INTL(\"${npc.cpp.intl.8731}\")\nELSE\n   Conversation\n   INTL(\"${npc.cpp.intl.5250}\")\nENDIF\n\n\nEndTalk",
        Map.of()));
